import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&/^note(update|delete)_/.test(w))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
const rows=[];for(const kind of ['update','delete'])for(const action of ['preview','apply']){const valid=action==='preview'?{clipRef:'clip:clip-1',...(kind==='update'?{notes:[{id:1,pitch:48}]}:{noteIds:[1]})}:{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of Object.keys(valid)){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-1,0,1,1e308,'','x','a'.repeat(257)])cases.push({...valid,[key]:value});}if(action==='preview'&&kind==='update'){for(const field of ['id','pitch','start','duration','velocity','mute','probability','velocityDeviation','releaseVelocity','extra'])for(const value of [null,[],{},false,true,-128,-1,0,0.5,1,127,128,1e308,''])cases.push({...valid,notes:[{id:1,pitch:48,[field]:value}]});for(const notes of [[{id:1}],[],[{},{}],[{id:1,pitch:40},{id:1,pitch:41}],[{id:1,start:4,duration:1}],[{id:1,velocity:100.5}],[{id:1,probability:0.5,mute:true}]])cases.push({...valid,notes});}if(action==='preview'&&kind==='delete')for(const noteIds of [[1,1],[1,2],[-1],[1.5],[null],['1'],[true],[1e308]])cases.push({...valid,noteIds});for(const args of cases){const host=new McpHost(new DeterministicLiveSimulator());let result;try{result=clean(await host[action==='preview'?'liveNoteEditPreviewAsync':'liveNoteEditApplyAsync'](1,args,kind));}catch(e){result={error:e.message};}rows.push({kind,action,args,result});}}
const fences=[];const host=new McpHost(new DeterministicLiveSimulator());for(let j=0;j<128;j++){const notes=[];for(let k=0;k<12;k++){const n={id:(j*17+k*13)%127,pitch:(j*7+k*11)%128,start:((j*3+k*5)%100)/3,duration:0.25,velocity:(j+k)%128,channel:1};if(j&1)n.mute=Boolean(k%2);if(j&2)n.probability=k/12;if(j&4)n.velocityDeviation=k-8;if(j&8)n.releaseVelocity=64+k;if(j&16)delete n.id;if(j&32)n.start=-n.start;if(j&64)n.duration=1e-7;notes.push(n);}fences.push({notes,fence:host.noteFence(notes),content:host.noteContentFence(notes)});}
const workflows=[];const scenarios=['normal','expire','epoch','identity-edit','note-edit','revision-edit','missing-identity','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-other-identity','undo-other-note','undo-epoch','missing-optionals','multiple','recover-after','recover-no-effect','recover-partial','recover-external'];
for(const kind of ['update','delete'])for(const scenario of scenarios){
const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();let fault='',fired=false,afterInvoke=false;const clip=()=>sim.state.tracks[0].clips[0];if(scenario==='missing-identity')delete clip().objectIdentity;if(scenario==='missing-optionals')for(const field of ['mute','probability','velocityDeviation','releaseVelocity'])delete clip().notes[0][field];if(['multiple','recover-partial','recover-external'].includes(scenario))clip().notes.push({...clip().notes[0],id:2,start:1,pitch:40});
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure');}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure');}const noEffect=!fired&&fault.endsWith('no-effect');let actual=i;if(!fired&&fault==='recover-partial'){actual=structuredClone(i);if(kind==='delete')actual.args.noteIds=actual.args.noteIds.slice(0,1);else actual.args.notes=actual.args.notes.slice(0,1);}const result=noEffect?{ok:true}:sim.invoke(actual);if(noEffect)fired=true;else cache.set(key,result);afterInvoke=true;if(!fired&&fault==='recover-external'){fired=true;clip().notes.push({id:100,pitch:80,start:2,duration:1,velocity:90,channel:1});throw Error('injected operation failure');}if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}return result;}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
const host=new McpHost(adapter),results=[],states=[];const ids=clip().notes.map(n=>n.id);const args={clipRef:'clip:clip-1',...(kind==='update'?{notes:ids.map(id=>({id,pitch:48,velocity:96,mute:true}))}:{noteIds:ids})};const preview=await host.liveNoteEditPreviewAsync(1,args,kind);results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
if(txid){const record=host.noteEditTransactions.get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action,idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(action==='apply'?await host.liveNoteEditApplyAsync(results.length+1,args,kind,controller.signal):await host.liveUndoAsync(results.length+1,args)));states.push(clean(record));}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')clip().objectIdentity='other';if(scenario==='note-edit')clip().notes[0].velocity=60;if(scenario==='revision-edit')clip().notesRevision='manual';if(scenario.startsWith('apply-')||scenario.startsWith('recover-'))fault=scenario;
for(const key of (scenario.startsWith('recover-')?['apply-key']:['apply-key','other-key','apply-key']))await perform('apply',key);fault='';fired=false;afterInvoke=false;
if(scenario==='undo-other-identity')clip().objectIdentity='other';if(scenario==='undo-other-note')clip().notes.push({id:100,pitch:80,start:2,duration:1,velocity:90,channel:1});if(scenario==='undo-epoch')sim.reconnect();if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-other-note','undo-epoch'].includes(scenario))fault=scenario;
for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key');}
workflows.push({kind,scenario,results,states,calls,state:sim.state});}
fs.writeFileSync(new URL('host-note-edit-oracle.json',import.meta.url),JSON.stringify({rows,fences,workflows}));console.log({rows:rows.length,fences:fences.length,workflows:workflows.length});
